// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

// Training fixtures; historical performance uses deployed mainnet bytecode.
contract ABIRegions {
    function tuple(address a, uint256 b) external pure returns (address, uint256) { return (a,b); }
    function mixed(address a, uint128 b, int24 c, bool d, bytes4 e) external pure returns(address,uint128,int24,bool,bytes4) { return(a,b,c,d,e); }
    function three(uint256 a,uint256 b,uint256 c) external pure returns(uint256,uint256,uint256){return(a,b,c);}
    function two(address a,address b) external pure returns(address,address){return(a,b);}
    function transferFrom(address a,address b,uint256 c) external pure returns(address,address,uint256){return(a,b,c);}
    function payload(bytes calldata b) external pure returns(bytes memory){return b;}
    function text(string calldata b) external pure returns(string memory){return b;}
    function array(uint256[] calldata a) external pure returns(uint256[] memory){return a;}
    function addresses(address[] calldata a) external pure returns(address[] memory){return a;}
    function complex(address a,bytes calldata b,uint256[] calldata c) external pure returns(address,bytes memory,uint256[] memory){return(a,b,c);}
    function fromMemory(bytes memory b) external pure returns(bytes memory){return b;}
    function decode(bytes memory b) external pure returns(address,uint256){return abi.decode(b,(address,uint256));}
    function fixedArray(uint256[3] calldata a) external pure returns(uint256[3] memory){return a;}
    function nested(bytes[] calldata a) external pure returns(bytes[] memory){return a;}
}
